-- Set session-level isolation level
SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
BEGIN TRAN;
    SELECT * FROM Orders WHERE Status = 'Pending';
    -- This SELECT holds shared locks only during the read
COMMIT TRAN;

-- Set to REPEATABLE READ for a session
SET TRANSACTION ISOLATION LEVEL REPEATABLE READ;
BEGIN TRAN;
    SELECT * FROM Customers WHERE CustomerId = 42;
    -- Shared locks held until COMMIT/ROLLBACK
    SELECT * FROM Customers WHERE CustomerId = 42;
    -- Re-reading the same row returns the same data
COMMIT TRAN;

-- Use table hints for a single query
SELECT * FROM Orders WITH (NOLOCK) WHERE Status = 'Pending';
SELECT * FROM Orders WITH (UPDLOCK, ROWLOCK) WHERE OrderId = 1001;

-- Set SNAPSHOT isolation at the database level first
ALTER DATABASE [AdventureWorks] SET ALLOW_SNAPSHOT_ISOLATION ON;
SET TRANSACTION ISOLATION LEVEL SNAPSHOT;
